     1→/**
     2→ * NAJIKA CODE EDITOR - Grüne Matrix-Ästhetik
     3→ * Inspiriert von Claude Code Interface
     4→ */
     5→
     6→const CodeEditor = {
     7→    isOpen: false,
     8→    overlay: null,
     9→
    10→    open() {
    11→        if (this.isOpen) return;
    12→        this.isOpen = true;
    13→
    14→        // Erstelle Overlay
    15→        this.overlay = document.createElement('div');
    16→        this.overlay.id = 'codeEditorOverlay';
    17→        this.overlay.innerHTML = `
    18→            <div class="code-editor-container">
    19→                <div class="code-editor-header">
    20→                    <div class="header-left">
    21→                        <span class="terminal-icon">⬢</span>
    22→                        <span class="title">NAJIKA TERMINAL</span>
    23→                        <span class="status-indicator">●</span>
    24→                        <button class="header-btn" onclick="CodeEditor.listFiles()" title="Files neu laden">📂</button>
    25→                        <button class="header-btn" onclick="CodeEditor.saveFile()" title="Datei speichern">💾</button>
    26→                        <button class="header-btn" onclick="CodeEditor.executeCode()" title="Code ausführen">▶</button>
    27→                    </div>
    28→                    <button class="close-btn" onclick="CodeEditor.close()">✕</button>
    29→                </div>
    30→
    31→                <div class="code-editor-main">
    32→                    <!-- Linke Sidebar: File Explorer -->
    33→                    <div class="sidebar">
    34→                        <div class="sidebar-header">EXPLORER</div>
    35→                        <div class="file-tree">
    36→                            <div class="file-item folder">
    37→                                <span class="folder-icon">📁</span> C:\\NajikaCore
    38→                            </div>
    39→                            <div class="file-item file" onclick="CodeEditor.loadFile('najika_server.py')">
    40→                                <span class="file-icon">🐍</span> najika_server.py
    41→                            </div>
    42→                            <div class="file-item file" onclick="CodeEditor.loadFile('index.html')">
    43→                                <span class="file-icon">🌐</span> index.html
    44→                            </div>
    45→                        </div>
    46→                    </div>
    47→
    48→                    <!-- Center: Code-Editor Area -->
    49→                    <div class="editor-area">
    50→                        <div class="editor-tabs">
    51→                            <div class="tab active">
    52→                                <span>najika_prompt.txt</span>
    53→                                <button class="tab-close">×</button>
    54→                            </div>
    55→                        </div>
    56→                        <div class="editor-content">
    57→                            <textarea id="codeEditorTextarea" spellcheck="false"></textarea>
    58→                        </div>
    59→                    </div>
    60→
    61→                    <!-- Rechts: Najika Chat -->
    62→                    <div class="najika-assistant">
    63→                        <div class="assistant-header">
    64→                            <span class="najika-icon">🐊</span> NAJIKA AI
    65→                        </div>
    66→                        <div class="chat-messages" id="najikaCodeChat">
    67→                            <div class="message assistant">
    68→                                <strong>[SHIRO-ANALYSE]</strong> Terminal-Zugriff gewährt.
    69→                                <br><br>
    70→                                <strong>[MEGUMIN]</strong> *leuchtende Augen* Mr.K! Lass uns Code-EXPLOSIONEN machen! 💥
    71→                            </div>
    72→                        </div>
    73→                        <div class="chat-input-container">
    74→                            <input type="text" id="najikaCodeInput" placeholder="Frag Najika etwas..." />
    75→                            <button onclick="CodeEditor.sendMessage()">⏎</button>
    76→                        </div>
    77→                    </div>
    78→                </div>
    79→
    80→                <!-- Bottom: Terminal Output -->
    81→                <div class="terminal-output">
    82→                    <div class="terminal-header">TERMINAL OUTPUT</div>
    83→                    <div class="terminal-content" id="terminalOutput">
    84→                        <span class="prompt">najika@terminal:~$</span> <span class="cursor">_</span>
    85→                    </div>
    86→                </div>
    87→            </div>
    88→        `;
    89→
    90→        document.body.appendChild(this.overlay);
    91→
    92→        // Initial Code laden
    93→        this.loadDefaultCode();
    94→
    95→        // File-Liste laden
    96→        this.listFiles();
    97→
    98→        // Keyboard Shortcuts
    99→        this.setupKeyboardShortcuts();
   100→
   101→        // Focus auf Chat Input
   102→        setTimeout(() => {
   103→            document.getElementById('najikaCodeInput')?.focus();
   104→        }, 300);
   105→    },
   106→
   107→    setupKeyboardShortcuts() {
   108→        const textarea = document.getElementById('codeEditorTextarea');
   109→        if (!textarea) return;
   110→
   111→        textarea.addEventListener('keydown', (e) => {
   112→            // Ctrl+S: Speichern
   113→            if (e.ctrlKey && e.key === 's') {
   114→                e.preventDefault();
   115→                this.saveFile();
   116→            }
   117→            // F5: Ausführen
   118→            if (e.key === 'F5') {
   119→                e.preventDefault();
   120→                this.executeCode();
   121→            }
   122→            // Ctrl+Enter: Ausführen
   123→            if (e.ctrlKey && e.key === 'Enter') {
   124→                e.preventDefault();
   125→                this.executeCode();
   126→            }
   127→            // Tab: 4 Spaces einfügen (statt Tab-Navigation)
   128→            if (e.key === 'Tab') {
   129→                e.preventDefault();
   130→                const start = textarea.selectionStart;
   131→                const end = textarea.selectionEnd;
   132→                textarea.value = textarea.value.substring(0, start) + '    ' + textarea.value.substring(end);
   133→                textarea.selectionStart = textarea.selectionEnd = start + 4;
   134→            }
   135→        });
   136→    },
   137→
   138→    close() {
   139→        if (!this.isOpen) return;
   140→        this.isOpen = false;
   141→        if (this.overlay) {
   142→            this.overlay.remove();
   143→            this.overlay = null;
   144→        }
   145→    },
   146→
   147→    loadDefaultCode() {
   148→        const textarea = document.getElementById('codeEditorTextarea');
   149→        if (!textarea) return;
   150→
   151→        textarea.value = `# NAJIKA AI SYSTEM
   152→# Grüße Mr.K! Bereit für Code-EXPLOSIONEN!
   153→
   154→def najika_greeting():
   155→    print("[SHIRO-ANALYSE] System bereit...")
   156→    print("[MEGUMIN] EXPLOSION!!! 💥")
   157→
   158→# Befehle:
   159→# - help() - Zeige alle Najika-Befehle
   160→# - status() - Systemstatus
   161→# - execute(code) - Code ausführen
   162→`;
   163→    },
   164→
   165→    async loadFile(filename) {
   166→        notify(`📄 Lade ${filename}...`, 'info');
   167→
   168→        try {
   169→            const response = await fetch('/api/file/read', {
   170→                method: 'POST',
   171→                headers: {'Content-Type': 'application/json'},
   172→                body: JSON.stringify({path: filename})
   173→            });
   174→            const data = await response.json();
