   187→        const wallSpan = FALLBACK_DEFAULTS.span;
   188→        const positions = [
   189→            { pos: [0, wallHeight / 2, -wallSpan], size: [wallSpan * 2, wallHeight, wallThickness] },
   190→            { pos: [0, wallHeight / 2, wallSpan], size: [wallSpan * 2, wallHeight, wallThickness] },
   191→            { pos: [-wallSpan, wallHeight / 2, 0], size: [wallThickness, wallHeight, wallSpan * 2] },
   192→            { pos: [wallSpan, wallHeight / 2, 0], size: [wallThickness, wallHeight, wallSpan * 2] }
   193→        ];
   194→        positions.forEach(info => {
   195→            const wall = new THREE.Mesh(new THREE.BoxGeometry(...info.size), wallMaterial);
   196→            wall.position.set(info.pos[0], info.pos[1], info.pos[2]);
   197→            wall.castShadow = true;
   198→            wall.receiveShadow = true;
   199→            scene.add(wall);
