   203→
   204→    function installEventHandlers() {
   205→        window.addEventListener('resize', onWindowResize, false);
   206→        window.addEventListener('keydown', onKeyDown, false);
   207→        window.addEventListener('keyup', onKeyUp, false);
   208→
   209→        const canvas = renderer.domElement;
   210→        orbitCanvas = canvas;
   211→        canvas.style.touchAction = 'none';
   212→        canvas.addEventListener('pointerdown', onPointerDown, { passive: false });
   213→        canvas.addEventListener('pointermove', onPointerMove, { passive: false });
   214→        canvas.addEventListener('pointerup', onPointerUp, { passive: false });
   215→        canvas.addEventListener('pointerleave', onPointerUp, { passive: false });
   216→        canvas.addEventListener('pointercancel', onPointerUp, { passive: false });
   217→        canvas.addEventListener('wheel', onWheel, { passive: false });
   218→    }
   219→
   220→    function ensureKayKitLoader() {
   221→        if (!window.KayKitLoader) {
   222→            return;
   223→        }
   224→        document.addEventListener('kaykit:configReady', scheduleRoomBuild, false);
   225→        document.addEventListener('kaykit:modelLoaded', onKayKitModelLoaded, false);
   226→        if (typeof KayKitLoader.init === 'function') {
   227→            KayKitLoader.init();
   228→        }
   229→    }
   230→
   231→    function startAnimationLoop() {
   232→        const loop = () => {
   233→            animationHandle = requestAnimationFrame(loop);
   234→            const delta = clock ? clock.getDelta() : 0.016;
   235→            updateCharacter(delta);
   236→            updateCamera(delta);
   237→            if (pendingRoomBuild) {
   238→                buildRoom();
   239→            }
   240→            // Update Dungeon Combat (enemies & combat logic)
   241→            if (typeof window.DungeonCombat !== 'undefined' && DungeonCombat.isActive()) {
   242→                DungeonCombat.updateCombat();
   243→            }
   244→            renderer.render(scene, camera);
   245→        };
   246→        loop();
   247→    }
   248→
   249→    function onWindowResize() {
   250→        const container = getContainer();
   251→        if (!container || !camera || !renderer) {
   252→            return;
   253→        }
   254→        camera.aspect = container.clientWidth / container.clientHeight;
   255→        camera.updateProjectionMatrix();
   256→        renderer.setSize(container.clientWidth, container.clientHeight);
   257→    }
   258→
   259→    function onKeyDown(event) {
   260→        activeKeys.add(event.code);
   261→        // F-Taste: Najika dreht sich zum Spieler
   262→        if (event.code === 'KeyF') {
   263→            faceCharacter();
   264→        }
   265→    }
   266→
   267→    function onKeyUp(event) {
   268→        activeKeys.delete(event.code);
   269→    }
   270→
   271→    function onPointerDown(event) {
   272→        if (!orbitCanvas) {
   273→            return;
   274→        }
   275→        event.preventDefault();
   276→
   277→        // FIX: Blur room dropdown to prevent W key from switching rooms
   278→        const roomDropdown = document.getElementById('room');
   279→        if (roomDropdown && document.activeElement === roomDropdown) {
   280→            roomDropdown.blur();
   281→        }
   282→
   283→        activePointers.set(event.pointerId, { x: event.clientX, y: event.clientY });
   284→
   285→        if (activePointers.size === 1) {
   286→            // Single touch/click: Rotate
   287→            pointerMode = 'rotate';
   288→            dragStartPos = { x: event.clientX, y: event.clientY };
   289→            dragStartYaw = orbitYaw;
   290→            dragStartPitch = orbitPitch;
   291→        } else if (activePointers.size === 2 && cameraMode === CAMERA_MODES.ORBIT) {
   292→            // Two touches: Pinch to zoom (nur in Orbit)
   293→            pointerMode = 'pinch';
   294→            pinchStartDist = computePointerDistance();
   295→            pinchBaseDistance = orbitDistance;
   296→        }
   297→    }
   298→
   299→    function onPointerMove(event) {
   300→        if (!activePointers.has(event.pointerId)) {
   301→            return;
   302→        }
   303→        activePointers.set(event.pointerId, { x: event.clientX, y: event.clientY });
   304→
   305→        if (pointerMode === 'pinch' && activePointers.size === 2 && cameraMode === CAMERA_MODES.ORBIT) {
   306→            const dist = computePointerDistance();
   307→            if (pinchStartDist > 0) {
   308→                const ratio = dist / pinchStartDist;
   309→                if (ratio > 0) {
   310→                    orbitDistance = clamp(pinchBaseDistance / ratio, ORBIT_MIN_DIST, ORBIT_MAX_DIST);
   311→                }
   312→            }
   313→        } else if (pointerMode === 'rotate' && activePointers.size === 1) {
   314→            const dx = event.clientX - dragStartPos.x;
   315→            const dy = event.clientY - dragStartPos.y;
   316→            orbitYaw = dragStartYaw - dx * 0.005;
   317→            orbitPitch = clamp(dragStartPitch - dy * 0.003, ORBIT_MIN_PITCH, ORBIT_MAX_PITCH);
   318→        }
   319→    }
   320→
   321→    function onPointerUp(event) {
   322→        activePointers.delete(event.pointerId);
   323→        if (activePointers.size === 0) {
   324→            pointerMode = null;
   325→        } else if (activePointers.size === 1 && pointerMode === 'pinch') {
   326→            // Switched from pinch back to rotate
   327→            pointerMode = 'rotate';
   328→            const remaining = Array.from(activePointers.values())[0];
   329→            dragStartPos = { x: remaining.x, y: remaining.y };
   330→            dragStartYaw = orbitYaw;
   331→            dragStartPitch = orbitPitch;
   332→        }
   333→    }
   334→
   335→    function onWheel(event) {
   336→        if (cameraMode !== CAMERA_MODES.ORBIT) {
   337→            return;
   338→        }
   339→        event.preventDefault();
   340→        const delta = Math.sign(event.deltaY) * 1.5;
   341→        orbitDistance = clamp(orbitDistance + delta, ORBIT_MIN_DIST, ORBIT_MAX_DIST);
   342→    }
   343→
   344→    function computePointerDistance() {
   345→        const ptrs = Array.from(activePointers.values());
   346→        if (ptrs.length < 2) return 0;
   347→        const dx = ptrs[0].x - ptrs[1].x;
   348→        const dy = ptrs[0].y - ptrs[1].y;
   349→        return Math.sqrt(dx * dx + dy * dy);
   350→    }
   351→
   352→    function onKayKitModelLoaded(event) {
   353→        const modelName = event && event.detail && event.detail.name;
   354→        if (!characterReady && modelName && modelName.includes('wand')) {
   355→            attachStaffToCharacter();
   356→        }
   357→        scheduleRoomBuild();
   358→    }
   359→
   360→    function scheduleRoomBuild() {
   361→        pendingRoomBuild = true;
   362→    }
   363→
   364→    function buildRoom() {
   365→        pendingRoomBuild = false;
   366→
   367→        if (roomGroup) {
   368→            scene.remove(roomGroup);
   369→            disposeHierarchy(roomGroup);
   370→            roomGroup = null;
   371→        }
   372→
   373→        let config = getRoomConfig(currentRoomName);
   374→        let assetsReady = config ? roomAssetsAvailable(config) : false;
   375→
   376→        if (!config || !assetsReady) {
   377→            usingFallbackRoom = true;
   378→            currentRoomSpan = FALLBACK_DEFAULTS.span;
   379→            showFallbackRoom(true);
   380→            applyPalette(null);
   381→            resetCharacterPosition(null);
   382→            return;
   383→        }
   384→
   385→        usingFallbackRoom = false;
   386→        showFallbackRoom(false);
   387→
   388→        const span = resolveSpan(config);
   389→        currentRoomSpan = span;
   390→
   391→        // 🏰 DUNGEON GENERATOR für Keller
   392→        if (currentRoomName === 'Schwarze Mühle – Keller' && window.DungeonGenerator) {
   393→            const dungeonLevel = DungeonGenerator.currentLevel || 1;
   394→            const dungeon = DungeonGenerator.generateDungeon(dungeonLevel, span);
   395→            config = DungeonGenerator.applyDungeonToRoom(config, dungeon);
   396→            console.log(`🏰 Dungeon Level ${dungeonLevel} geladen in Keller`);
   397→        }
   398→
   399→        const group = new THREE.Group();
   400→
   401→        if (config.floor && config.floor.model) {
   402→            const floor = buildFloor(config.floor, span);
   403→            if (floor) {
   404→                group.add(floor);
   405→            }
   406→        }
   407→
   408→        if (config.walls && config.walls.model) {
   409→            const walls = buildWalls(config.walls, span, resolveWallHeight(config));
   410→            if (walls) {
   411→                group.add(walls);
   412→            }
   413→        }
   414→
   415→        if (Array.isArray(config.props)) {
   416→            config.props.forEach(prop => {
   417→                const instance = buildProp(prop);
   418→                if (instance) {
   419→                    group.add(instance);
   420→                }
   421→            });
   422→        }
   423→
   424→        roomGroup = group;
   425→        scene.add(roomGroup);
   426→
   427→        applyPalette(config.palette || null);
   428→        resetCharacterPosition(config.spawn || null);
   429→    }
   430→
   431→    function showFallbackRoom(visible) {
   432→        if (baseFloor) baseFloor.visible = visible;
   433→        if (gridHelper) gridHelper.visible = visible;
   434→        fallbackWalls.forEach(w => (w.visible = visible));
   435→    }
   436→
   437→    function getRoomConfig(name) {
   438→        if (!name || !window.KayKitLoader || typeof KayKitLoader.getRoomConfig !== 'function') {
   439→            return null;
   440→        }
   441→        try {
   442→            return KayKitLoader.getRoomConfig(name);
   443→        } catch (error) {
   444→            console.warn('Scene3D: failed to read room config', error);
   445→            return null;
   446→        }
   447→    }
   448→
   449→    function getKayKitDefaults() {
   450→        if (!window.KayKitLoader || typeof KayKitLoader.getConfig !== 'function') {
   451→            return { ...FALLBACK_DEFAULTS };
   452→        }
   453→        const cfg = KayKitLoader.getConfig();
   454→        if (!cfg || !cfg.defaults) {
   455→            return { ...FALLBACK_DEFAULTS };
   456→        }
   457→        return { ...FALLBACK_DEFAULTS, ...cfg.defaults };
   458→    }
   459→
   460→    function resolveSpan(config) {
   461→        if (typeof config.span === 'number') {
   462→            return config.span;
   463→        }
   464→        if (config.floor && typeof config.floor.span === 'number') {
   465→            return config.floor.span;
   466→        }
   467→        if (config.walls && typeof config.walls.span === 'number') {
   468→            return config.walls.span;
   469→        }
   470→        const defaults = getKayKitDefaults();
   471→        return defaults.span;
   472→    }
   473→
   474→    function resolveWallHeight(config) {
   475→        if (config.walls && typeof config.walls.height === 'number') {
   476→            return config.walls.height;
   477→        }
   478→        if (typeof config.wallHeight === 'number') {
   479→            return config.wallHeight;
   480→        }
   481→        const defaults = getKayKitDefaults();
   482→        return defaults.wallHeight;
   483→    }
   484→
   485→    function roomAssetsAvailable(config) {
   486→        if (!window.KayKitLoader) {
   487→            return false;
   488→        }
   489→        const required = new Set();
   490→        if (config.floor && config.floor.model) required.add(config.floor.model);
   491→        if (config.walls && config.walls.model) required.add(config.walls.model);
   492→        if (Array.isArray(config.props)) {
   493→            config.props.forEach(prop => {
   494→                if (prop && prop.model) required.add(prop.model);
   495→            });
   496→        }
   497→        for (const name of required) {
   498→            if (!KayKitLoader.hasModel || !KayKitLoader.hasModel(name)) {
   499→                return false;
   500→            }
   501→        }
   502→        return true;
   503→    }
   504→
   505→    function buildFloor(entry, span) {
   506→        const instance = makeModelInstance(entry);
   507→        if (!instance) return null;
   508→        // Skaliere Boden auf volle span-Größe
   509→        scaleUniformToSpan(instance, span);
   510→        // Mache Boden EXTREM flach (nur 5% Höhe) wie eine dünne Platte
   511→        instance.scale.y *= 0.05;
   512→        // Berechne BoundingBox um Boden korrekt zu positionieren
   513→        const box = new THREE.Box3().setFromObject(instance);
   514→        const floorHeight = box.max.y - box.min.y;
   515→        // Positioniere so dass OBERSEITE bei Y=0 ist (Unterseite darunter)
   516→        instance.position.y = -box.min.y - floorHeight;
   517→        applyEntryTransform(instance, entry);
   518→        return instance;
   519→    }
   520→
   521→    function buildWalls(entry, span, wallHeight) {
   522→        const base = makeModelInstance(entry);
   523→        if (!base) return null;
   524→
   525→        // Skaliere Wand-Modell auf die volle span-Breite
   526→        scaleAxisToSpan(base, 'x', span);
   527→
   528→        const group = new THREE.Group();
   529→        // Wände am RAND des Bodens positionieren (span / 2)
   530→        const half = span / 2;
