   591→        document.body.appendChild(notificationContainer);
   592→    }
   593→    const notif = document.createElement('div');
   594→    notif.className = `notification ${type}`;
   595→    notif.textContent = msg;
   596→    notif.onclick = () => { notif.style.animation = 'slideOutRight 0.3s'; setTimeout(() => notif.remove(), 300); };
   597→    notificationContainer.appendChild(notif);
   598→    setTimeout(() => { if (notif.parentElement) { notif.style.animation = 'slideOutRight 0.3s'; setTimeout(() => notif.remove(), 300); } }, 5000);
