   636→function setServerStatus(online) {
   637→    if (!statusDot || !statusText) return;
   638→    if (online) {
   639→        statusDot.classList.remove('offline');
   640→        statusText.textContent = 'Online';
   641→    } else {
   642→        statusDot.classList.add('offline');
   643→        statusText.textContent = 'Offline';
   644→    }
   645→}
   646→
   647→window.setServerStatus = setServerStatus;
   648→
   649→async function api(path, method = 'GET', body) {
   650→    const options = {
   651→        method,
   652→        headers: {'Content-Type': 'application/json'}
   653→    };
   654→    if (body) {
   655→        options.body = JSON.stringify(body);
   656→    }
   657→    try {
   658→        const response = await fetch(path, options);
   659→        if (!response.ok) {
   660→            throw new Error(response.status + ' ' + response.statusText);
   661→        }
   662→        const data = await response.json();
   663→        setServerStatus(true);
   664→        return data;
   665→    } catch (error) {
   666→        setServerStatus(false);
   667→        throw error;
   668→    }
   669→}
