   675→async function toggleCloud() {
   676→    try {
   677→        const info = await cloudStatus();
   678→        if (!info.enabled) {
   679→            const pin = prompt('PIN eingeben:');
   680→            if (!pin) return;
   681→            await api('/api/cloud/enable', 'POST', {pin});
   682→        } else {
   683→            await api('/api/cloud/disable', 'POST');
   684→        }
   685→    } catch (error) {
   686→        console.warn('Cloud-Umschaltung fehlgeschlagen.', error);
   687→        notify('Cloud aktuell nicht erreichbar.');
   688→    } finally {
   689→        applyCloudBtn();
   690→    }
   691→}
