   695→    if (!btn) return;
   696→    try {
   697→        const info = await cloudStatus();
   698→        btn.style.display = 'inline-block';
   699→        btn.textContent = info.enabled ? 'Cloud deaktivieren' : 'Cloud aktivieren';
   700→        if (providerLabel) {
   701→            providerLabel.textContent = 'Provider: ' + (info.provider || 'lokal');
   702→        }
   703→    } catch (error) {
   704→        btn.style.display = 'none';
   705→        if (providerLabel) {
   706→            providerLabel.textContent = 'Provider: offline';
   707→        }
   708→    }
   709→}
