  1552→<!-- FINISHER QTE SYSTEM -->
  1553→<script>
  1554→// Finisher QTE - Vanilla JS (konvertiert von React)
  1555→let finisherQTE = null;
  1556→
  1557→class FinisherQTE {
  1558→  constructor() {
  1559→    this.active = false;
  1560→    this.meter = 0;
  1561→    this.duration = 3000;
  1562→    this.startTime = 0;
  1563→    this.mashCount = 0;
  1564→    this.lastMashTime = 0;
  1565→    this.mashCooldown = 100;
  1566→    this.updateInterval = null;
  1567→    this.onCompleteCallback = null;
  1568→    this.keyListener = null;
  1569→  }
  1570→
  1571→  start(onComplete) {
  1572→    this.active = true;
  1573→    this.meter = 0;
  1574→    this.startTime = Date.now();
  1575→    this.mashCount = 0;
  1576→    this.lastMashTime = 0;
  1577→    this.onCompleteCallback = onComplete;
  1578→
  1579→    console.log('🔥 FINISHER QTE GESTARTET!');
  1580→
  1581→    this.showUI();
  1582→    this.updateInterval = setInterval(() => this.update(0.016), 16);
  1583→
  1584→    this.keyListener = (e) => {
  1585→      if (e.code === 'Space' && this.active) {
  1586→        e.preventDefault();
  1587→        this.onMash();
  1588→      }
  1589→    };
  1590→    document.addEventListener('keydown', this.keyListener);
  1591→
  1592→    return { active: true, message: '🔥 FINISH!!! 🔥', instruction: 'SPACE schnell drücken!' };
  1593→  }
  1594→
  1595→  onMash() {
  1596→    if (!this.active) return { success: false };
  1597→
  1598→    const now = Date.now();
  1599→    if (now - this.lastMashTime < this.mashCooldown) return { success: false };
  1600→
  1601→    this.lastMashTime = now;
  1602→    this.mashCount++;
  1603→    this.meter = Math.min(100, this.meter + 5);
  1604→
  1605→    console.log(`Mash ${this.mashCount}: Meter ${this.meter}%`);
  1606→    this.updateUI();
  1607→
  1608→    return { success: true, meter: this.meter, mashCount: this.mashCount };
  1609→  }
  1610→
  1611→  update(delta) {
  1612→    if (!this.active) return null;
  1613→
  1614→    const now = Date.now();
  1615→    const elapsed = now - this.startTime;
  1616→
  1617→    if (elapsed >= this.duration) {
  1618→      this.finish();
  1619→      return null;
  1620→    }
  1621→
  1622→    if (now - this.lastMashTime > 200) {
  1623→      this.meter = Math.max(0, this.meter - (delta * 10));
  1624→    }
  1625→
  1626→    this.updateUI();
  1627→    return { active: true, meter: this.meter, timeLeft: this.duration - elapsed, mashCount: this.mashCount };
  1628→  }
  1629→
  1630→  finish() {
  1631→    if (!this.active) return null;
  1632→
  1633→    this.active = false;
  1634→    if (this.updateInterval) clearInterval(this.updateInterval);
  1635→    if (this.keyListener) document.removeEventListener('keydown', this.keyListener);
  1636→
  1637→    const multiplier = 1.0 + (this.meter / 100);
  1638→    let rank = 'C';
  1639→    if (this.meter >= 90) rank = 'S';
  1640→    else if (this.meter >= 70) rank = 'A';
  1641→    else if (this.meter >= 50) rank = 'B';
  1642→
  1643→    console.log(`✨ FINISHER! Meter: ${this.meter}%, Multiplier: ${multiplier.toFixed(2)}x, Rank: ${rank}`);
  1644→
  1645→    const messages = {
  1646→      'S': '✨ PERFEKT! MAXIMALER SCHADEN! ✨',
  1647→      'A': '🔥 EXCELLENT! KRITISCHER TREFFER! 🔥',
  1648→      'B': '⚡ GOOD! STARKER ANGRIFF! ⚡',
  1649→      'C': '💥 OK! Treffer gelandet! 💥'
  1650→    };
  1651→
  1652→    const result = {
  1653→      active: false,
  1654→      completed: true,
  1655→      meter: this.meter,
  1656→      multiplier: multiplier,
  1657→      mashCount: this.mashCount,
  1658→      rank: rank,
  1659→      message: messages[rank] || messages['C']
  1660→    };
  1661→
  1662→    this.hideUI();
  1663→    if (this.onCompleteCallback) this.onCompleteCallback(result);
  1664→
  1665→    return result;
  1666→  }
  1667→
  1668→  cancel() {
  1669→    if (!this.active) return null;
  1670→    this.active = false;
  1671→    if (this.updateInterval) clearInterval(this.updateInterval);
  1672→    if (this.keyListener) document.removeEventListener('keydown', this.keyListener);
  1673→    this.hideUI();
  1674→    return { active: false, completed: false, cancelled: true, message: 'Finisher abgebrochen!' };
  1675→  }
  1676→
  1677→  isActive() { return this.active; }
  1678→
  1679→  showUI() {
  1680→    let overlay = document.getElementById('qteOverlay');
  1681→    if (!overlay) {
  1682→      overlay = document.createElement('div');
  1683→      overlay.id = 'qteOverlay';
  1684→      overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.8);display:flex;align-items:center;justify-content:center;z-index:10000;animation:qteFlash 0.5s;';
  1685→      overlay.innerHTML = `
  1686→        <div style="background:linear-gradient(135deg,#1a1a2e,#2d2d44);border:3px solid #ff6b00;border-radius:20px;padding:2rem;text-align:center;box-shadow:0 0 40px rgba(255,107,0,0.6);animation:qteShake 0.3s infinite;">
  1687→          <div style="font-size:3rem;font-weight:bold;color:#ff6b00;text-shadow:0 0 20px #ff6b00;margin-bottom:1rem;animation:qtePulse 0.5s infinite;">🔥 FINISH!!! 🔥</div>
  1688→          <div style="font-size:1.5rem;color:#fff;margin-bottom:2rem;font-weight:bold;">SPACE SCHNELL DRÜCKEN!</div>
  1689→          <div style="position:relative;width:400px;height:50px;background:#1a1a2e;border:2px solid #ff6b00;border-radius:25px;overflow:hidden;margin:0 auto 1rem;">
  1690→            <div id="qteMeterBar" style="position:absolute;left:0;top:0;height:100%;width:0%;background:linear-gradient(90deg,#ff6b00,#ff0000);transition:width 0.1s;box-shadow:0 0 20px rgba(255,107,0,0.8);"></div>
  1691→            <div id="qteMeterText" style="position:absolute;inset:0;display:flex;align-items:center;justify-content:center;font-size:1.5rem;font-weight:bold;color:#fff;text-shadow:2px 2px 4px #000;">0%</div>
  1692→          </div>
  1693→          <div style="font-size:1.2rem;color:#ccc;"><span id="qteTime">3.0s</span> | <span id="qteMashes">0 Mashes</span></div>
  1694→        </div>
  1695→      `;
  1696→      document.body.appendChild(overlay);
  1697→
  1698→      // CSS Animations
  1699→      const style = document.createElement('style');
  1700→      style.textContent = `
  1701→        @keyframes qteFlash { 0% { background: rgba(255,100,0,0.8); } 100% { background: rgba(0,0,0,0.8); } }
  1702→        @keyframes qteShake { 0%, 100% { transform: translateX(0); } 25% { transform: translateX(-5px); } 75% { transform: translateX(5px); } }
  1703→        @keyframes qtePulse { 0%, 100% { transform: scale(1); } 50% { transform: scale(1.1); } }
  1704→      `;
  1705→      document.head.appendChild(style);
  1706→    }
  1707→    overlay.style.display = 'flex';
  1708→    this.updateUI();
  1709→  }
  1710→
  1711→  updateUI() {
  1712→    const bar = document.getElementById('qteMeterBar');
  1713→    const text = document.getElementById('qteMeterText');
  1714→    const time = document.getElementById('qteTime');
  1715→    const mash = document.getElementById('qteMashes');
  1716→
  1717→    if (bar) bar.style.width = `${this.meter}%`;
  1718→    if (text) text.textContent = `${Math.floor(this.meter)}%`;
  1719→    if (time && this.active) {
  1720→      const left = Math.max(0, this.duration - (Date.now() - this.startTime));
  1721→      time.textContent = `${(left / 1000).toFixed(1)}s`;
  1722→    }
  1723→    if (mash) mash.textContent = `${this.mashCount} Mashes`;
  1724→  }
  1725→
  1726→  hideUI() {
  1727→    const overlay = document.getElementById('qteOverlay');
  1728→    if (overlay) overlay.style.display = 'none';
  1729→  }
  1730→}
  1731→
  1732→// Globale Instanz
  1733→finisherQTE = new FinisherQTE();
  1734→</script>
