  1736→<!-- EVOLUTION SYSTEM -->
  1737→<script>
  1738→// Evolution System - Simplified Digimon World Style
  1739→let evolutionSystem = null;
  1740→
  1741→class EvolutionSystem {
  1742→  constructor() {
  1743→    this.battleXP = 0;
  1744→    this.evolutionStage = 'rookie'; // rookie → champion → ultimate → mega
  1745→    this.totalVictories = 0;
  1746→  }
  1747→
  1748→  // Berechne Stage basierend auf XP
  1749→  calculateStage() {
  1750→    if (this.battleXP >= 1000) return 'mega';
  1751→    if (this.battleXP >= 500) return 'ultimate';
  1752→    if (this.battleXP >= 100) return 'champion';
  1753→    return 'rookie';
  1754→  }
  1755→
  1756→  // Füge XP hinzu und prüfe Evolution
  1757→  addXP(xp) {
  1758→    const oldStage = this.evolutionStage;
  1759→    this.battleXP += xp;
  1760→    this.evolutionStage = this.calculateStage();
  1761→
  1762→    console.log(`+${xp} XP! Total: ${this.battleXP} XP | Stage: ${this.evolutionStage}`);
  1763→
  1764→    // Evolution passiert?
  1765→    if (oldStage !== this.evolutionStage) {
  1766→      return {
  1767→        evolved: true,
  1768→        oldStage,
  1769→        newStage: this.evolutionStage,
  1770→        message: this.getEvolutionMessage(this.evolutionStage),
  1771→        battleXP: this.battleXP
  1772→      };
  1773→    }
  1774→
  1775→    return { evolved: false, battleXP: this.battleXP };
  1776→  }
  1777→
  1778→  // Evolution Messages
  1779→  getEvolutionMessage(stage) {
  1780→    const messages = {
  1781→      'champion': '⭐ Kuja! Ich verstehe jetzt besser was du willst!',
  1782→      'ultimate': '✨ Wir sind ein Team, Kuja! Ich kann fast alleine kämpfen!',
  1783→      'mega': '🌟 PERFEKT! Ich kenne dich jetzt so gut, Kuja!'
  1784→    };
  1785→    return messages[stage] || '';
  1786→  }
  1787→
  1788→  // Hole Stage-Icon
  1789→  getStageIcon(stage = null) {
  1790→    const icons = {
  1791→      'rookie': '🌱',
  1792→      'champion': '⭐',
  1793→      'ultimate': '✨',
  1794→      'mega': '🌟'
  1795→    };
  1796→    return icons[stage || this.evolutionStage] || '🌱';
  1797→  }
  1798→
  1799→  // Hole XP für nächste Evolution
  1800→  getXPForNextStage() {
  1801→    const thresholds = {
  1802→      'rookie': 100,
  1803→      'champion': 500,
  1804→      'ultimate': 1000,
  1805→      'mega': Infinity
  1806→    };
  1807→    return thresholds[this.evolutionStage];
  1808→  }
  1809→
  1810→  // Hole Progress %
  1811→  getProgressPercent() {
  1812→    const next = this.getXPForNextStage();
  1813→    if (next === Infinity) return 100;
  1814→
  1815→    const prev = this.evolutionStage === 'ultimate' ? 500 :
  1816→                 this.evolutionStage === 'champion' ? 100 : 0;
  1817→
  1818→    return Math.floor(((this.battleXP - prev) / (next - prev)) * 100);
  1819→  }
  1820→
  1821→  // Siege zählen
  1822→  addVictory() {
  1823→    this.totalVictories++;
  1824→  }
  1825→
  1826→  // Hole Status
  1827→  getStatus() {
  1828→    return {
  1829→      stage: this.evolutionStage,
  1830→      icon: this.getStageIcon(),
  1831→      battleXP: this.battleXP,
  1832→      nextStageXP: this.getXPForNextStage(),
  1833→      progress: this.getProgressPercent(),
  1834→      victories: this.totalVictories
  1835→    };
  1836→  }
  1837→}
  1838→
  1839→// Globale Instanz
  1840→evolutionSystem = new EvolutionSystem();
  1841→
  1842→// Zeige Evolution Notification
  1843→function showEvolutionNotification(evolutionResult) {
  1844→  if (!evolutionResult.evolved) return;
  1845→
  1846→  notify(`🎉 EVOLUTION! ${evolutionResult.oldStage.toUpperCase()} → ${evolutionResult.newStage.toUpperCase()}!`, 'info');
  1847→  notify(evolutionResult.message, 'info');
  1848→
  1849→  console.log('✨ EVOLUTION!', evolutionResult);
  1850→
  1851→  // TODO: Visual Evolution Effect (Fullscreen Animation)
  1852→}
